diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..975105e 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,47 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+const LINEAS = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("RF-006 T-601: sin descuentoGlobal el resultado no cambia", () => {
+  assert.deepEqual(calcularFactura(LINEAS, {}), { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 });
+});
+
+test("RF-006 T-602: 10 % global se descuenta antes de calcular el IVA", () => {
+  const f = calcularFactura(LINEAS, { descuentoGlobal: 10 });
+  assert.deepEqual(f, { descuentoGlobalCentavos: 1105, totalCentavos: 9945, ivaCentavos: 1293, netoCentavos: 8652 });
+});
+
+test("RF-006 T-603: 0 % y 100 % son válidos", () => {
+  assert.equal(calcularFactura(LINEAS, { descuentoGlobal: 0 }).totalCentavos, 11050);
+  const f = calcularFactura(LINEAS, { descuentoGlobal: 100 });
+  assert.deepEqual(f, { descuentoGlobalCentavos: 11050, totalCentavos: 0, ivaCentavos: 0, netoCentavos: 0 });
+});
+
+test("RF-006 T-604: descuentoGlobal inválido se rechaza", () => {
+  for (const d of [-1, 100.01, NaN, Infinity, "10", null]) {
+    assert.throws(() => calcularFactura(LINEAS, { descuentoGlobal: d }), RangeError, String(d));
+  }
+});
+
+test("RF-006 T-605: el resultado son centavos enteros", () => {
+  const f = calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 10001 }], { descuentoGlobal: 33.33 });
+  assert.equal(f.descuentoGlobalCentavos, 3333);
+  assert.equal(f.totalCentavos, 6668);
+  for (const v of Object.values(f)) assert.ok(Number.isInteger(v));
+});
+
+test("RF-006 T-606: emitirFactura con descuentoGlobal queda congelada", () => {
+  const f = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items: LINEAS, descuentoGlobal: 10 });
+  assert.ok(Object.isFrozen(f));
+  assert.equal(f.descuentoGlobalCentavos, 1105);
+  assert.equal(f.totalCentavos, 9945);
+  assert.equal(f.estado, "emitida");
+});
